  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);

  const trimmed = email.trim();
  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
  const errorText = touched && trimmed.length > 0 && !isValid ? 'Укажите корректный адрес, например name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо отправлено на ${trimmed}`,
      variant: 'success',
    });
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        maxWidth: 420,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: 20, color: 'var(--jx-text)' }}>
          Подписка на рассылку
        </h2>
        <p style={{ margin: 0, fontSize: 14, color: 'var(--jx-text-2)' }}>
          Раз в неделю присылаем обзор обновлений. Отписаться можно в один клик.
        </p>
      </div>

      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        placeholder="name@example.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        errorText={errorText}
        helperText={errorText ? undefined : 'Адрес используем только для рассылки'}
      />

      <JxButton type="submit" variant="primary" disabled={!isValid}>
        Подписаться
      </JxButton>

      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </form>
  );
}

